import heapq

def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    adj = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        bit = (1 << zone) if zone >= 0 else 0
        adj[u].append((v, cost, bit))
        adj[v].append((u, cost, bit))

    buy = [[] for _ in range(n)]
    for stop, z in stations:
        buy[stop].append((1 << z, prices[z]))

    num_masks = 1 << len(prices)
    INF = float('inf')
    dist = [[INF] * num_masks for _ in range(n)]
    dist[0][0] = 0
    pq = [(0, 0, 0)]  # (total_cost, u, mask)

    while pq:
        d, u, mask = heapq.heappop(pq)
        if u == n - 1:
            return d
        if d > dist[u][mask]:
            continue

        for bit, price in buy[u]:
            if not (mask & bit):
                nmask = mask | bit
                nd = d + price
                if nd < dist[u][nmask]:
                    dist[u][nmask] = nd
                    heapq.heappush(pq, (nd, u, nmask))

        for v, cost, bit in adj[u]:
            nd = d if (mask & bit) else d + cost
            if nd < dist[v][mask]:
                dist[v][mask] = nd
                heapq.heappush(pq, (nd, v, mask))

    return -1
